/* ==========================================================================
   State Education Department - Student Retention & Welfare Efficacy Platform
   Meng To Sketchbook Editorial Theme & Design System
   Typography: Instrument Serif (Display) + Newsreader (Body / Metrics)
   Palette: Warm Tactile Paper (#ECE7DC / #F7F4ED) & Deep Bistre Charcoal Ink (#2B2721)
   Light Botanical & Education EdTech Paper Wash Ground
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Newsreader:ital,opsz,wght@0,6..72,300..600;1,6..72,300..500&display=swap');

:root {
    --paper: #ece7dc;
    --paper-card: rgba(253, 251, 247, 0.88);
    --paper-solid: #fbf9f5;
    --ink: #2b2721;
    --ink-soft: rgba(43, 39, 33, 0.62);
    --ink-faint: rgba(43, 39, 33, 0.38);
    --hairline: rgba(43, 39, 33, 0.14);
    --earth: #9a6a3e;
    --earth-soft: rgba(154, 106, 62, 0.12);
    --brass: #c2a26a;
    --vermilion: #b34f3e;
    --moss: #486950;
    --display: 'Instrument Serif', Georgia, 'Times New Roman', serif;
    --font: 'Newsreader', Georgia, 'Times New Roman', serif;
    --track-caps: 0.18em;
    --track-nav: 0.06em;
}

/* --------------------------------------------------------------------------
   1. Complete Removal of Deploy Button & Header Dead Spacing
   -------------------------------------------------------------------------- */
.stDeployButton,
button[data-testid="stDeployButton"],
div[data-testid="stToolbar"] .stDeployButton,
[data-testid="stToolbarActions"],
[data-testid="manage-app-button"],
#MainMenu,
header[data-testid="stHeader"],
.viewerBadge_container__r5tak,
.viewerBadge_link__qRIco,
footer {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    pointer-events: none !important;
    width: 0 !important;
    height: 0 !important;
}

/* --------------------------------------------------------------------------
   2. Light Botanical Paper Wash Background Ground
   -------------------------------------------------------------------------- */
html, body, [class*="css"], .stApp {
    font-family: var(--font) !important;
    font-size: 16px;
    font-weight: 400;
    color: var(--ink) !important;
    background-color: var(--paper) !important;
    -webkit-font-smoothing: antialiased;
}

.stApp {
    background-image: 
        linear-gradient(180deg, rgba(236,231,220,0.35) 0%, rgba(236,231,220,0.72) 48%, rgba(236,231,220,0.92) 88%),
        url("data:image/jpeg;base64,") !important;
    background-position: center top !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
}

/* Light subtle botanical illustrations on left & right margins */
.stApp::before {
    content: "";
    position: fixed;
    bottom: 0;
    left: 0;
    width: clamp(140px, 16vw, 260px);
    height: clamp(280px, 35vh, 480px);
    background: url("data:image/png;base64,") left bottom / contain no-repeat;
    opacity: 0.28;
    pointer-events: none;
    z-index: 0;
}

.stApp::after {
    content: "";
    position: fixed;
    bottom: 0;
    right: 0;
    width: clamp(130px, 14vw, 230px);
    height: clamp(260px, 32vh, 440px);
    background: url("data:image/png;base64,") right bottom / contain no-repeat;
    opacity: 0.26;
    pointer-events: none;
    z-index: 0;
}

::selection {
    background: rgba(43, 39, 33, 0.85);
    color: var(--paper);
}

/* Headings in Instrument Serif */
h1, h2, h3, h4, .stMarkdown h1, .stMarkdown h2, .stMarkdown h3, .stMarkdown h4 {
    font-family: var(--display) !important;
    font-weight: 400 !important;
    color: var(--ink) !important;
    letter-spacing: 0.015em;
}

h1 { font-size: 2.25rem !important; }
h2 { font-size: 1.85rem !important; }
h3 { font-size: 1.45rem !important; }
h4 { font-size: 1.2rem !important; }

/* Eliminate free top dead space */
.main .block-container {
    padding-top: 0.4rem !important;
    padding-bottom: 3.5rem !important;
    padding-left: clamp(1.5rem, 3vw, 3rem) !important;
    padding-right: clamp(1.5rem, 3vw, 3rem) !important;
    max-width: 1380px !important;
    position: relative;
    z-index: 1;
}

/* --------------------------------------------------------------------------
   3. Editorial Top Masthead & Navigation Bar
   -------------------------------------------------------------------------- */
.editorial-top-masthead {
    text-align: center;
    padding: 12px 16px 14px 16px;
    margin-bottom: 12px;
    background: linear-gradient(180deg, rgba(246, 243, 235, 0.94), rgba(246, 243, 235, 0.65) 55%, rgba(246, 243, 235, 0));
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--hairline);
}

.top-meta-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 4px;
    padding: 0 4px;
}

.top-kicker {
    font-family: var(--font);
    font-size: 11.5px;
    letter-spacing: var(--track-caps);
    text-transform: uppercase;
    color: var(--ink-soft);
    font-weight: 400;
}

.top-live-badge {
    font-family: var(--font);
    font-size: 11px;
    letter-spacing: 0.05em;
    color: var(--moss);
    background: rgba(72, 105, 80, 0.1);
    padding: 2px 10px;
    border-radius: 999px;
    border: 1px solid rgba(72, 105, 80, 0.2);
}

.top-project-title {
    font-family: var(--display) !important;
    font-size: clamp(26px, 2.6vw, 34px) !important;
    font-weight: 400 !important;
    letter-spacing: 0.015em !important;
    color: var(--ink) !important;
    margin: 4px 0 0 0 !important;
    line-height: 1.15 !important;
}

.editorial-nav-divider {
    height: 1px;
    background: var(--hairline);
    margin: 12px 0 20px 0;
}

/* Top Nav Page Links (st.page_link) */
div[data-testid="stPageLink-NavLink"] {
    background: rgba(253, 251, 247, 0.85) !important;
    border: 1px solid rgba(43, 39, 33, 0.14) !important;
    border-radius: 999px !important;
    padding: 5px 12px !important;
    font-family: var(--font) !important;
    font-size: 13px !important;
    letter-spacing: var(--track-nav) !important;
    color: var(--ink) !important;
    transition: all 0.18s ease !important;
    box-shadow: 0 1px 2px rgba(43, 39, 33, 0.03) !important;
    text-align: center !important;
}

div[data-testid="stPageLink-NavLink"]:hover {
    background: rgba(154, 106, 62, 0.14) !important;
    border-color: var(--earth) !important;
    color: var(--earth) !important;
    transform: translateY(-1px) !important;
}

/* --------------------------------------------------------------------------
   4. Executive Plaque Header
   -------------------------------------------------------------------------- */
.gov-header {
    background: #2b2721;
    color: var(--paper);
    padding: 24px 32px;
    border-radius: 12px;
    margin-bottom: 22px;
    border: 1px solid var(--hairline);
    box-shadow: 0 4px 16px rgba(43, 39, 33, 0.12), 0 1px 3px rgba(43, 39, 33, 0.08);
    position: relative;
    overflow: hidden;
}

.gov-header::after {
    content: "";
    position: absolute;
    top: -40%;
    right: -5%;
    width: 280px;
    height: 280px;
    background: radial-gradient(circle, rgba(194, 162, 106, 0.18) 0%, rgba(194, 162, 106, 0) 70%);
    border-radius: 50%;
    pointer-events: none;
}

.gov-header h1 {
    font-family: var(--display) !important;
    font-size: 30px !important;
    font-weight: 400 !important;
    letter-spacing: 0.02em !important;
    margin: 0 0 6px 0 !important;
    color: #ffffff !important;
    line-height: 1.2 !important;
}

.gov-header p {
    font-family: var(--font) !important;
    font-size: 15px !important;
    color: rgba(247, 244, 237, 0.75) !important;
    margin: 0 !important;
    line-height: 1.5 !important;
}

.gov-badge {
    display: inline-block;
    background: rgba(194, 162, 106, 0.2);
    color: #e8d7ba;
    padding: 3px 12px;
    border-radius: 999px;
    font-family: var(--font);
    font-size: 11px;
    font-weight: 400;
    text-transform: uppercase;
    letter-spacing: var(--track-caps);
    margin-bottom: 8px;
    border: 1px solid rgba(194, 162, 106, 0.35);
}

/* --------------------------------------------------------------------------
   5. Tactile Editorial KPI Cards (Paper Ground & Ink)
   -------------------------------------------------------------------------- */
.kpi-card {
    background: var(--paper-card);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid rgba(43, 39, 33, 0.12);
    border-radius: 10px;
    padding: 16px 18px;
    box-shadow: 0 2px 6px rgba(43, 39, 33, 0.04), 0 1px 2px rgba(43, 39, 33, 0.03);
    transition: transform 0.18s ease, box-shadow 0.18s ease;
    margin-bottom: 14px;
    position: relative;
    overflow: hidden;
}

.kpi-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 3px;
    height: 100%;
    background: var(--earth);
    opacity: 0.75;
}

.kpi-card:hover {
    box-shadow: 0 6px 14px rgba(43, 39, 33, 0.08);
    transform: translateY(-2px);
    border-color: rgba(43, 39, 33, 0.24);
}

.kpi-title {
    font-family: var(--font);
    font-size: 11.5px;
    font-weight: 500;
    color: var(--ink-faint);
    text-transform: uppercase;
    letter-spacing: var(--track-caps);
    margin-bottom: 5px;
}

.kpi-value {
    font-family: var(--display);
    font-size: 32px;
    font-weight: 400;
    color: var(--ink);
    letter-spacing: 0.01em;
    line-height: 1.15;
    margin-bottom: 3px;
}

.kpi-subtitle {
    font-family: var(--font);
    font-size: 12px;
    font-weight: 300;
    color: var(--ink-soft);
}

/* --------------------------------------------------------------------------
   6. Status Pills & Badges (Botanical / Parchment Tones)
   -------------------------------------------------------------------------- */
.pill-critical {
    background-color: #f7ebe8;
    color: #9c3022;
    font-family: var(--font);
    font-weight: 500;
    padding: 3px 9px;
    border-radius: 5px;
    font-size: 12px;
    border: 1px solid rgba(179, 79, 62, 0.3);
    display: inline-block;
}

.pill-high {
    background-color: #faede2;
    color: #8c4217;
    font-family: var(--font);
    font-weight: 500;
    padding: 3px 9px;
    border-radius: 5px;
    font-size: 12px;
    border: 1px solid rgba(154, 106, 62, 0.3);
    display: inline-block;
}

.pill-medium {
    background-color: #fbf5e6;
    color: #7b5916;
    font-family: var(--font);
    font-weight: 500;
    padding: 3px 9px;
    border-radius: 5px;
    font-size: 12px;
    border: 1px solid rgba(194, 162, 106, 0.35);
    display: inline-block;
}

.pill-low {
    background-color: #edf2ee;
    color: #2b5134;
    font-family: var(--font);
    font-weight: 500;
    padding: 3px 9px;
    border-radius: 5px;
    font-size: 12px;
    border: 1px solid rgba(72, 105, 80, 0.3);
    display: inline-block;
}

/* --------------------------------------------------------------------------
   7. Alert Banners & Callouts
   -------------------------------------------------------------------------- */
.alert-box {
    background-color: rgba(244, 246, 248, 0.85);
    backdrop-filter: blur(8px);
    border-left: 3px solid #4a677a;
    padding: 13px 18px;
    border-radius: 6px;
    margin: 16px 0;
    font-family: var(--font);
    font-size: 14.5px;
    color: var(--ink);
    line-height: 1.6;
    border: 1px solid rgba(74, 103, 122, 0.15);
    border-left-width: 4px;
}

.alert-box-warning {
    background-color: rgba(252, 246, 234, 0.88);
    backdrop-filter: blur(8px);
    border-left: 4px solid var(--earth);
    padding: 13px 18px;
    border-radius: 6px;
    margin: 16px 0;
    font-family: var(--font);
    font-size: 14.5px;
    color: #6e441c;
    line-height: 1.6;
    border: 1px solid rgba(154, 106, 62, 0.2);
    border-left-width: 4px;
}

.alert-box-critical {
    background-color: rgba(251, 240, 238, 0.88);
    backdrop-filter: blur(8px);
    border-left: 4px solid var(--vermilion);
    padding: 13px 18px;
    border-radius: 6px;
    margin: 16px 0;
    font-family: var(--font);
    font-size: 14.5px;
    color: #8c2a1c;
    line-height: 1.6;
    border: 1px solid rgba(179, 79, 62, 0.2);
    border-left-width: 4px;
}

/* --------------------------------------------------------------------------
   8. Sidebar & Interactive Inputs
   -------------------------------------------------------------------------- */
div[data-testid="stSidebar"] {
    background-color: rgba(244, 240, 230, 0.94) !important;
    backdrop-filter: blur(12px) !important;
    border-right: 1px solid rgba(43, 39, 33, 0.12) !important;
    font-family: var(--font) !important;
}

div[data-testid="stSidebar"] h1,
div[data-testid="stSidebar"] h2,
div[data-testid="stSidebar"] h3 {
    font-family: var(--display) !important;
    font-weight: 400 !important;
    color: var(--ink) !important;
}

div[data-testid="stSidebar"] label {
    font-family: var(--font) !important;
    font-size: 13px !important;
    font-weight: 500 !important;
    color: var(--ink) !important;
}

.stButton>button {
    background: var(--ink) !important;
    color: var(--paper) !important;
    font-family: var(--font) !important;
    font-size: 14px !important;
    font-weight: 400 !important;
    letter-spacing: var(--track-nav) !important;
    border-radius: 6px !important;
    border: 1px solid var(--hairline) !important;
    padding: 0.45rem 1.25rem !important;
    transition: background-color 0.18s ease, color 0.18s ease !important;
}

.stButton>button:hover {
    background: var(--earth) !important;
    color: #ffffff !important;
    box-shadow: 0 2px 8px rgba(154, 106, 62, 0.25) !important;
}

/* Tabs */
.stTabs [data-baseweb="tab-list"] {
    gap: 6px;
    background-color: rgba(43, 39, 33, 0.05);
    padding: 4px;
    border-radius: 8px;
    border-bottom: none;
}

.stTabs [data-baseweb="tab"] {
    font-family: var(--font) !important;
    border-radius: 6px;
    padding: 6px 14px;
    font-size: 14px;
    color: var(--ink-soft);
    border: none;
}

.stTabs [aria-selected="true"] {
    background-color: var(--paper-solid) !important;
    color: var(--ink) !important;
    font-weight: 500;
    box-shadow: 0 1px 3px rgba(43, 39, 33, 0.08);
}

/* Metric component override */
div[data-testid="stMetricValue"] {
    font-family: var(--display) !important;
    font-size: 28px !important;
    font-weight: 400 !important;
    color: var(--ink) !important;
}

div[data-testid="stMetricLabel"] {
    font-family: var(--font) !important;
    font-size: 12px !important;
    color: var(--ink-faint) !important;
    letter-spacing: var(--track-caps);
    text-transform: uppercase;
}

/* DataFrame table container */
div[data-testid="stDataFrame"] {
    background: rgba(253, 251, 247, 0.9) !important;
    border: 1px solid var(--hairline) !important;
    border-radius: 8px !important;
    overflow: hidden;
}
